-- This file contains code generated by deepseek, so may contain some bugs.

local theme_dir = os.getenv("HOME") .. "/.local/share/fcitx5/themes/auto-gen"

-- Svgs adapted from Ori-fcitx5 (https://github.com/Reverier-Xu/Ori-fcitx5),
-- MIT License, Copyright (c) 2024 Reverier Xu.
-- Only the path data of each svg is kept, colors and sizes are replaced.
local panel_path =
"m 16.487805,4.4878049 h 15.024391 c 8.461953,0 12,3.3636279 12,12.0000001 v 15.024391 c 0,8.392186 -3.398512,12 -12,12 H 16.487805 c -8.3921861,0 -12.0000001,-3.538047 -12.0000001,-12 V 16.487805 c 0,-8.6363722 3.4682791,-12.0000001 12.0000001,-12.0000001 z"
local highlight_path =
"m 16.299999,4 h 15.4 C 41.967687,4 44,5.9625437 44,16.299999 v 15.4 C 44,41.932804 42.072338,44 31.699999,44 h -15.4 C 6.0671949,44 4,41.932804 4,31.699999 v -15.4 C 4,6.0671948 6.0403037,4 16.299999,4 Z"

-- chevron of the submenu arrow, centered at (24,24)
local arrow_path = "m 20,17.4 6.6,6.6 -6.6,6.6"

---Build a svg from an Ori shape with the given colors.
---@param path_data string The shape path of the Ori svg
---@param fill string
---@param stroke string|nil
---@param stroke_width number|nil
---@return string
local function build_svg(path_data, fill, stroke, stroke_width)
	local style = "fill:" .. fill .. ";fill-opacity:1;stroke:none;stroke-linecap:round;stroke-linejoin:round"
	if stroke then
		style = style .. ";stroke:" .. stroke .. ";stroke-width:" .. tostring(stroke_width or 1)
	end
	return table.concat({
		'<?xml version="1.0" encoding="UTF-8"?>',
		'<svg width="48" height="48" viewBox="0 0 48 48" version="1.1" xmlns="http://www.w3.org/2000/svg">',
		'  <path style="' .. style .. '" d="' .. path_data .. '" />',
		'</svg>',
		'',
	}, "\n")
end

---Wrap a stroke style path, all strokes are rounded to match the Ori shapes.
---@param style string
---@param path_data string
---@return string
local function stroke_svg(style, path_data)
	return table.concat({
		'<?xml version="1.0" encoding="UTF-8"?>',
		'<svg width="48" height="48" viewBox="0 0 48 48" version="1.1" xmlns="http://www.w3.org/2000/svg">',
		'  <path style="' .. style .. '" d="' .. path_data .. '" />',
		'</svg>',
		'',
	}, "\n")
end

---Build a rounded chevron, a bit chubby to stay cute at small sizes.
---@param color string
---@param stroke_width number
---@return string
local function chevron_svg(color, stroke_width)
	local style = "fill:none;stroke:" .. color .. ";stroke-width:" .. tostring(stroke_width)
		.. ";stroke-linecap:round;stroke-linejoin:round"
	return stroke_svg(style, arrow_path)
end

---Build a rounded check mark for check boxes.
---@param color string
---@param stroke_width number
---@return string
local function check_svg(color, stroke_width)
	local style = "fill:none;stroke:" .. color .. ";stroke-width:" .. tostring(stroke_width)
		.. ";stroke-linecap:round;stroke-linejoin:round"
	return stroke_svg(style, "m 16,24.6 5.6,5.6 10.4,-12.4")
end

---@param path string
---@param content string
local function write_file(path, content)
	local f = assert(io.open(path, "w"))
	f:write(content)
	f:close()
end

---Rasterize the svgs, fcitx5 can only load png images.
---@param name string
local function rasterize(name)
	os.execute(string.format(
		"rsvg-convert -f png -o %s/png/%s.png %s/%s.svg",
		theme_dir, name, theme_dir, name
	))
end

---Generate the panel/highlight/menu svgs from the scheme, then rasterize them.
---@param scheme tdf.ColorScheme
local function gen_svgs(scheme)
	local png_dir = theme_dir .. "/png"
	os.execute("mkdir -p " .. png_dir)

	write_file(theme_dir .. "/panel.svg", build_svg(panel_path, scheme.bg.common, scheme.bg.border, 0.5))
	write_file(theme_dir .. "/highlight.svg", build_svg(highlight_path, scheme.bg.active))
	-- menu assets
	write_file(theme_dir .. "/radio.svg", check_svg(scheme.brand, 5))
	write_file(theme_dir .. "/arrow.svg", chevron_svg(scheme.fg.subtle, 4.5))

	for _, name in ipairs({ "panel", "highlight", "radio", "arrow" }) do
		rasterize(name)
	end

	return png_dir
end

---@param scheme tdf.ColorScheme
---@return string
return function(scheme)
	local png_dir = gen_svgs(scheme)

	local template = [[
